 devices:{name:'required',type:['router','olt','onu','cpe'],model:'text',location:'text',ip:'text',serial:'text',customer:'text',phone:'text',address:'text',parentId:'@olts',zoneId:'@zones',odbId:'@odbs',odbPort:'positiveOptional',speedId:'@speeds',presetId:'@presets',pon:'text',latitude:'number',longitude:'number',driver:['none','routeros-rest','routeros-script','snmp','olt-gateway'],snmpPort:'positiveOptional',snmpMapping:'long',endpoint:'url',externalId:'text',signalThreshold:'number'},
 cpe:{name:'required',type:['cpe'],cpeCategory:['Customer router','ONT / ONU','Wi-Fi access point','Other CPE'],vendor:'text',model:'text',firmware:'text',serial:'text',macAddress:'text',customer:'text',phone:'tel',address:'text',location:'text',ip:'text',observedViaRouterId:'@routers',linkedOnuId:'@onuRecords',managementMethod:['Unknown','TR-069 / GenieACS','Vendor controller','Customer managed','Local access only','Unsupported'],onboardingStatus:['Observed','Needs installation','Awaiting customer or technician','Ready for enrollment','Managed / check-in observed','Unsupported'],identityVerified:'checkbox',locationVerified:'checkbox',installationVerified:'checkbox',customerHandoff:'checkbox',remoteEnrollmentVerified:'checkbox',notes:'long'},
 jobs:{title:'required',type:['Installation','Repair / no internet','Fibre signal','TR-069 setup','Relocation','Other'],priority:['Normal','Urgent'],oltId:'@olts',deviceId:'@devices',customer:'text',phone:'tel',address:'text',details:'long',assigneeId:'@team',due:'date',status:['Open','In progress','Done']},
 tickets:{title:'required',category:['Billing & wallet','MikroTik','OLT','TR-069','Load balancing','Account & login','Something else'],subscriberId:'@subscribers',customer:'text',details:'long',priority:['Normal','Urgent'],assigneeId:'@team',status:['Open','In progress','Resolved']},
 alerts:{title:'required',deviceId:'@devices',details:'long',severity:['info','warning','critical'],status:['Open','Acknowledged','Resolved']},
 zones:{name:'required',description:'long',latitude:'number',longitude:'number'},odbs:{name:'required',zoneId:'@zones',capacity:'positive',address:'text',latitude:'number',longitude:'number',notes:'long'},
 speeds:{name:'required',download:'positive',fixedUpstream:'nonnegative',notes:'long'},presets:{name:'required',zoneId:'@zones',odbId:'@odbs',namePattern:'text',notes:'long'},
 cables:{name:'required',cableType:['Backbone','Feeder','Distribution','Drop','Other'],fromId:'@endpoints',fromPon:'text',toId:'@endpoints',cores:'positive',length:'number',route:'long',status:['Planned','Installed','Damaged']},
 closures:{name:'required',closureType:['Splice closure','FAT / terminal box','Joint box','Manhole','Pole','ODF','Other'],trays:'nonnegative',zoneId:'@zones',address:'text',latitude:'number',longitude:'number',details:'long'},
 splices:{name:'required',closureId:'@closures',fromCableId:'@cables',fromCore:'positive',toCableId:'@cables',toCore:'positive',loss:'number'},
 stock:{name:'required',category:['ONUs / routers for customers','MikroTik / routers','OLTs and cards','SFP modules','Fibre cable','Splitters','Closures / FATs / ODBs','Patch cords / pigtails','Connectors / sleeves','Tools','Other'],sku:'text',unit:'text',minimum:'nonnegative',unitCost:'nonnegative',location:'text',notes:'long'},stockMoves:{stockId:'@stock',quantity:'number',reason:'required'},
 profiles:{name:'required',vendor:'required',vlan:'positive',download:'positive',upload:'positive',tr069Url:'url',description:'long'},
